import{_ as a,c as t,o,ag as r}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Android-virtual-device","description":"","frontmatter":{"title":"Android-virtual-device"},"headers":[],"relativePath":"general/android-virtual-device.md","filePath":"general/android-virtual-device.md","lastUpdated":null}'),i={name:"general/android-virtual-device.md"};function n(l,e,s,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="android-virtual-device" tabindex="-1">Android-virtual-device <a class="header-anchor" href="#android-virtual-device" aria-label="Permalink to &quot;Android-virtual-device&quot;">​</a></h1><h2 id="android-virtual-emulator" tabindex="-1">Android Virtual Emulator <a class="header-anchor" href="#android-virtual-emulator" aria-label="Permalink to &quot;Android Virtual Emulator&quot;">​</a></h2><p>Return to <a href="/general/virtual-environments.html">Environment</a> page</p><p>The Android Virtual Device (AVD) Emulator, part of Android Studio, is a tool for running and debugging Android applications. It is free, open-source, and does not require an internet connection after installation.</p><p>This is a part of the <a href="/general/dfp-guide.html">guide</a> and the [section ## Installation 1. Download Android Studio from <a href="/research/">https://developer.android.com/studio/install here</a>. 2. Follow the installation instructions for your operating system.</p><h3 id="windows-run-the-downloaded-installer-and-follow-the-prompts" tabindex="-1">Windows - Run the downloaded installer and follow the prompts. <a class="header-anchor" href="#windows-run-the-downloaded-installer-and-follow-the-prompts" aria-label="Permalink to &quot;Windows - Run the downloaded installer and follow the prompts.&quot;">​</a></h3><h3 id="macos-ensure-homebrew-is-installed-shell-bin-bash-c-curl-fssl-https-raw-githubusercontent-com-homebrew-install-head-install-sh" tabindex="-1">MacOS - Ensure Homebrew is installed: ``SHELL /bin/bash -c “$(curl -fsSL <a href="https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh</a>)” <a class="header-anchor" href="#macos-ensure-homebrew-is-installed-shell-bin-bash-c-curl-fssl-https-raw-githubusercontent-com-homebrew-install-head-install-sh" aria-label="Permalink to &quot;MacOS - Ensure Homebrew is installed: ``SHELL /bin/bash -c “$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)”&quot;">​</a></h3><ul><li>Install using Homebrew:</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>\n<span class="line"><span>brew install --cask android-studio</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="linux-extract-the-downloaded-tar-gz-file-run-the-studio-sh-script-from-the-extracted-directory" tabindex="-1">Linux - Extract the downloaded tar.gz file. - Run the <code>studio.sh</code> script from the extracted directory. <a class="header-anchor" href="#linux-extract-the-downloaded-tar-gz-file-run-the-studio-sh-script-from-the-extracted-directory" aria-label="Permalink to &quot;Linux - Extract the downloaded tar.gz file. - Run the `studio.sh` script from the extracted directory.&quot;">​</a></h3><p>Launch Android Studio and go to “More Actions” &gt; “AVD Manager.” In the AVD Manager, select “Create Virtual Device.” Choose a device to emulate. Select a system image (Android version) to use. (Expect about a 1GB download per image.) Name your emulator and click “Finish.”</p><h3 id="installing-applications" tabindex="-1">Installing Applications <a class="header-anchor" href="#installing-applications" aria-label="Permalink to &quot;Installing Applications&quot;">​</a></h3><p>&#39;&#39; Download applications as “.apk” files from trusted sources like F-Droid. &#39;&#39; Store .apk files in a central location for the organization. &#39;&#39; Drag and drop the .apk file onto the running emulator to install.</p><p><strong>Recommended FOSS App Markets:</strong> - <a href="https://aurora-store.en.uptodown.com/android" target="_blank" rel="noreferrer">Aurora Store</a> - <a href="https://f-droid.org/" target="_blank" rel="noreferrer">F-Droid</a></p><ol><li><p>Migration To create a backup of your AVD:</p></li><li><p>Locate your AVD folder. Common locations: #&#39;&#39; Windows: <code>C:\\Users\\&amp;lt;YourUserName&amp;gt;\\.android\\</code> #* Linux/Mac: <code>~/.android</code></p></li><li><p>In the <code>.android</code> folder, locate the AVD you want to export.</p></li><li><p>Compress the <code>device.avd</code> folder and the <code>device.ini</code> file (replace ‘device’ with the name of your AVD).</p></li><li><p>Move the compressed files to the new location. To import the AVD on another machine: 1. Uncompress the files in the appropriate <code>.android</code> directory. 2. If moving across OS, adjust the file paths in <code>device.ini</code> to match the new system’s format. 3. In AVD Manager, go to “Import,” select the backed-up AVD. If an error occurs, use the “Repair” option.</p></li></ol>',15)])])}const m=a(i,[["render",n]]);export{p as __pageData,m as default};
